 a={}
 for r in (rows or []):
  k=(r.get('keys') or [''])[0]
  d=a.setdefault(k,{'c':0,'i':0,'w':0.0})
  imp=(r.get('impressions') or 0)
  d['c']+=(r.get('clicks') or 0)
  d['i']+=imp
  d['w']+=(r.get('position') or 0.0)*imp
 return {k:{'clicks':v['c'],'impressions':v['i'],'ctr':(v['c']/v['i'] if v['i'] else 0.0),'position':(v['w']/v['i'] if v['i'] else 0.0)} for k,v in a.items()}
